void test_gimp_image_roundtrip(Gimp *gimp, gboolean with_unusual_stuff, gboolean compat_paths, gboolean use_gimp_2_8_features)
{
  gchar *temp_filename = NULL;
  GimpImage *image = NULL;
  GimpImage *loaded_image = NULL;

  // Create the main image
  image = gimp_image_new(100, 100, GIMP_RGB_IMAGE);
  g_return_if_fail(image != NULL);

  // Apply unusual features if requested
  if (with_unusual_stuff)
  {
    // Add unusual features to the image
    // (Implementation of unusual features is not provided in the specification)
  }

  // Apply compatibility paths if requested
  if (compat_paths)
  {
    // Apply compatibility settings
    // (Implementation of compatibility settings is not provided in the specification)
  }

  // Apply GIMP 2.8 features if requested
  if (use_gimp_2_8_features)
  {
    // Apply GIMP 2.8 features
    // (Implementation of GIMP 2.8 features is not provided in the specification)
  }

  // Create a temporary file name
  temp_filename = g_strdup_printf("/tmp/gimp-test-XXXXXX.xcf");
  if (!mktemp(temp_filename))
  {
    g_free(temp_filename);
    return;
  }

  // Save the image to the temporary file
  if (!gimp_file_save(GIMP_FILE_SAVE_OVERWRITE, NULL, NULL, temp_filename, temp_filename, image))
  {
    g_free(temp_filename);
    return;
  }

  // Load the image from the temporary file
  loaded_image = gimp_file_load(temp_filename, temp_filename, NULL);

  // Check if the loaded image is valid
  if (loaded_image == NULL)
  {
    g_message("Failed to load the saved image.");
  }
  else
  {
    // Verify that the loaded image is valid
    // (Implementation of image verification is not provided in the specification)

    // Clean up the loaded image
    g_object_unref(loaded_image);
  }

  // Clean up
  g_unlink(temp_filename);
  g_free(temp_filename);
  g_object_unref(image);
}
